    (0xf71732e7b8352325f809668e1b009ffc3dc19328d132b54e81e473d7f648294e, 12657701),
    (0x6027c27181d8020601e17009e966ad2a30b19d3224d9394ef83c6c7224ec3a49, 12718636),
    (0x49487690068106472e53d16d6b001620a82d17e5bff2c3e08fd39bd58d1d4408, 12718642),
    (0x0590053c23917cd3db33a6c0676fbb19e661608e63b1e5f8bb5349e61ceb5a27, 12719405),
    (0xfd2ed3b8bf5b12912940c3cfe4e7d776c615707c6f25f70759f5aeef91f5dbb9, 12719467),
    (0xee10337800e84f0c9babf97491a58788f0970080a7dba7d9e265869908be6dd3, 13087706),
    (0xd6933246ed90c8369b1a888937ffa420469d0c774654868a093b4b69230cf45b, 13087897),
    (0x352ee78f9cf9e606d6ad91f42514b3f27d6563f362d2b773b79f38e70f9c95fa, 13098160),
    (0x13ab89cb0a3ac98661cfabc23c9ca386ab624823f34ee91e25bbafe777e4c290, 13098183),
    (0x5fe74f88124ceaf96f6c1c5b10f19b0b167de1aea09c154c34d71ccbcd2cdd1c, 13132632),
    (0xa39ce1d8363f1799c9e1d5bf4fb37f0f8245ac821751109fd0e337135c8f9f5f, 13132805),
    (0x3360b57fac26e4e22aed53d84fe5bb4fa04b12121d0187c0fd072548acfff82d, 13132815),
    (0x95dd45a41ac29dfdfd7ede23788bdd6daca3959f6bac69ed03edadc1b64d8955, 13319640),
    (0xcb32a7356a6930dafabc4af11484cd7ce5f0c2abef389ffdc40e5de651772d81, 13319647),
    (0x1e655e2afb27f312126503e814813a75f04de0ff0b6e42d9fc62dab73596c6d8, 13319691),
    (0xbd595df6dcfd677c394dbf9cce8112543260c684d50220401bc858b4e79a16e4, 14370264),
    (0xc74d748314e4645bf973ceb8fb59d1e73f6b20e0ee6af5ad1507d80522166e52, 14370317)
), requested_blocks AS (
  SELECT DISTINCT expected_block AS block_number FROM requested
)
, block_trades AS (
 SELECT d.* FROM dex.trades d
 JOIN requested_blocks b ON b.block_number = d.block_number
 WHERE d.blockchain = 'ethereum'
   AND d.block_number BETWEEN 10000835 AND 15400000
   AND d.block_month BETWEEN DATE '2020-05-01' AND DATE '2022-08-01'
   AND d.block_time >= TIMESTAMP '2020-05-04 00:00:00'
   AND d.block_time < TIMESTAMP '2022-08-25 00:00:00'
), touched_pools AS (
 SELECT DISTINCT d.block_number, d.project_contract_address
 FROM block_trades d JOIN requested r ON r.tx_hash = d.tx_hash
)
SELECT d.project, d.version, d.block_number, d.block_time, d.evt_index,
       concat('0x',to_hex(d.tx_hash)) AS tx_hash,
       concat('0x',to_hex(d.project_contract_address)) AS project_contract_address,
       concat('0x',to_hex(d.tx_from)) AS tx_from,
       concat('0x',to_hex(d.tx_to)) AS tx_to,
       concat('0x',to_hex(d.token_bought_address)) AS token_bought_address,
       concat('0x',to_hex(d.token_sold_address)) AS token_sold_address,
       CAST(d.token_bought_amount_raw AS VARCHAR) AS token_bought_amount_raw,
       CAST(d.token_sold_amount_raw AS VARCHAR) AS token_sold_amount_raw,
       r.tx_hash IS NOT NULL AS is_candidate_transaction
FROM block_trades d LEFT JOIN requested r ON r.tx_hash = d.tx_hash
WHERE r.tx_hash IS NOT NULL OR EXISTS (
 SELECT 1 FROM touched_pools p WHERE p.block_number = d.block_number
 AND p.project_contract_address = d.project_contract_address
)
ORDER BY d.block_number, d.tx_hash, d.evt_index, d.project, d.version
-- Decoded records supplement raw logs. Missing decoding does not prove no swap.
-- Preserve raw amounts as text when importing the result into R.

